{"code": "def check_lambda_debug(lam):
    if lam == 0:
        return False, "lam=0"
    D = lam**2 * (lam + 1) * (lam - 3)
    if D < 0:
        return False, "D < 0"
    sqrtD = D**0.5
    x1 = (lam + 1 + sqrtD) / (2 * lam)
    x2 = (lam + 1 - sqrtD) / (2 * lam)

    def f(x):
        return lam * x * (1 - x)

    for x in [x1, x2]:
        if 0 <= x <= 1:
            fx = f(x)
            ffx = f(fx)
            print(f"lam={lam}, x={x}, fx={fx}, ffx={ffx}, fx!=x: {abs(fx-x) > 1e-9}")
            if abs(fx - x) > 1e-9:
                if abs(ffx - x) < 1e-9:
                    return True, "Found"
    return False, "Not found"

print(check_lambda_debug(3.5))
print(check_lambda_debug(4.0))
print(check_lambda_debug(3.0))"}

